pub fn miro_rf_main(ctx: &Ctx) -> Script {
    miro_rf_main_run(ctx, MiroRfMainStep::Start, Vec::new()).map(|_| ())
}

pub fn miro_rf_main_onenable(ctx: &Ctx) -> Script {
    miro_rf_main_run(ctx, MiroRfMainStep::OnEnable, Vec::new()).map(|_| ())
}

